for n in range(N):
    for w in range(W):
        inflow = 0
        outflow = 0

        if w > 0:
            inflow += xWest[n, w-1]
        if n > 0:
            inflow += xNorth[n-1, w]

        if w < W-1:
            outflow += xWest[n, w]
        if n < N-1:
            outflow += xNorth[n, w]

        if n == 0 and w == 0:
            rhs = -1
        elif n == N-1 and w == W-1:
            rhs = 1
        else:
            rhs = 0

        model.addConstr(inflow - outflow == rhs)

for n in range(N):
    for w in range(W-1):
        model.addConstr(xWest[n, w] >= 0)

for n in range(N-1):
    for w in range(W):
        model.addConstr(xNorth[n, w] >= 0)
